<?php
require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/integrations.php';$config=integrationConfig('nonceblox_mysql');$error='';$message='';$jobs=[];$applicants=[];
try{if(($config['status']??'')!=='configured')throw new RuntimeException('Configure the NonceBlox database in Integrations first.');$remote=new PDO('mysql:host='.$config['host'].';port='.($config['port']?:3306).';dbname='.$config['database'].';charset=utf8mb4',$config['username'],integrationSecret($config,'password'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_TIMEOUT=>5]);$jobs=$remote->query('SELECT id,title,`desc`,tags,`date`,location,form_fields FROM career ORDER BY id DESC LIMIT 100')->fetchAll();$applicants=$remote->query('SELECT id,fname,lname,email,phone,remark,job_position,`date`,highest_qualification,ctc,city,state,exctc,file,equity,career_id,country FROM career_request ORDER BY id DESC LIMIT 250')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf']??'')){if(($_POST['action']??'')!=='sync')throw new RuntimeException('Invalid sync action.');$local=db();$jobStmt=$local->prepare('INSERT INTO jobs(title,description) VALUES(?,?)');$existingJobs=$local->prepare('SELECT id FROM jobs WHERE title=? LIMIT 1');foreach($jobs as $job){$existingJobs->execute([$job['title']]);if(!$existingJobs->fetchColumn())$jobStmt->execute([$job['title'],$job['desc']]);}$candidateStmt=$local->prepare('INSERT INTO candidates(id,name,role_title,email,phone,country_name,score,stage,source_name,skills_json,experience_json,analysis_json,stored_file,created_at) VALUES(?,?,?,?,?,?,0,\'Applied\',\'NonceBlox website\',\'[]\',\'{}\',\'{}\',?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),role_title=VALUES(role_title),email=VALUES(email),phone=VALUES(phone),country_name=VALUES(country_name),stored_file=VALUES(stored_file)');foreach($applicants as $a){$id='WEB-'.substr(hash('sha256','nonceblox-career-'.$a['id']),0,20);$name=trim($a['fname'].' '.$a['lname'])?:'Website applicant';$created=date('Y-m-d H:i:s',strtotime($a['date']?:'now'));$candidateStmt->execute([$id,$name,$a['job_position']?:'Candidate',$a['email']?:null,$a['phone']?:null,$a['country']?:null,$a['file']?:null,$created]);}$message=count($jobs).' jobs and '.count($applicants).' applicants synchronized.';}}
catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Source connection failed. Check hostname, permissions and firewall.';}
$activePage='sources';$pageTitle='Source sync · ResumeIQ';$pageStyles='<style>.sync-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin:12px 0}.sync-stat{padding:15px}.sync-stat strong{display:block;font-size:21px}.sync-stat span{font-size:9px;color:var(--muted)}.sync-table{padding:15px;overflow:auto}.sync-table table{width:100%;border-collapse:collapse;font-size:9px}.sync-table th,.sync-table td{text-align:left;padding:9px;border-bottom:1px solid var(--line);white-space:nowrap}.notice{padding:10px;border-radius:8px;margin:10px 0;font-size:10px}.ok{background:var(--green-soft);color:var(--green)}.err{background:#fff1f3;color:var(--danger)}@media(max-width:650px){.sync-stats{grid-template-columns:1fr}}</style>';require __DIR__.'/views/partials/header.php';?>
<section class="page-head"><div><div class="kicker"><i class="fa-solid fa-rotate"></i> Website source</div><h1>NonceBlox career sync</h1><p>Read-only remote preview. Import into ResumeIQ happens only when you press Sync now.</p></div><?php if(!$error):?><form method="post"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="action" value="sync"><button class="btn btn-primary"><i class="fa-solid fa-rotate"></i>Sync now</button></form><?php endif?></section><?php if($message):?><div class="notice ok"><?=htmlspecialchars($message)?></div><?php endif?><?php if($error):?><div class="notice err"><?=htmlspecialchars($error)?> <a href="integrations.php">Open integrations</a></div><?php endif?><section class="sync-stats"><article class="panel sync-stat"><strong><?=count($jobs)?></strong><span>Remote jobs</span></article><article class="panel sync-stat"><strong><?=count($applicants)?></strong><span>Remote applicants</span></article><article class="panel sync-stat"><strong><?=count(array_filter($applicants,fn($a)=>!empty($a['file'])))?></strong><span>Resume file references</span></article></section><section class="panel sync-table"><h2>Applicant preview</h2><table><thead><tr><th>Name</th><th>Job</th><th>Email</th><th>Location</th><th>Qualification</th><th>CTC</th><th>Resume</th></tr></thead><tbody><?php foreach($applicants as $a):?><tr><td><?=htmlspecialchars(trim($a['fname'].' '.$a['lname']))?></td><td><?=htmlspecialchars($a['job_position'])?></td><td><?=htmlspecialchars($a['email'])?></td><td><?=htmlspecialchars(implode(', ',array_filter([$a['city'],$a['state'],$a['country']])))?></td><td><?=htmlspecialchars($a['highest_qualification'])?></td><td><?=htmlspecialchars($a['ctc'].' / '.$a['exctc'])?></td><td><?=htmlspecialchars($a['file']?:'None')?></td></tr><?php endforeach?></tbody></table></section>
